# Find diagonal adjacencies - fixed iteration order
def has_diagonal_neighbor(grid, row, col, value):
    h, w = len(grid), len(grid[0])
    # Check 4 diagonal positions
    for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
        nr, nc = row + dr, col + dc
        if 0 <= nr < h and 0 <= nc < w:
            if grid[nr][nc] == value:
                return True
    return False

