def find_changes(input_grid, output_grid):
    changes = []
    for r in range(min(len(input_grid), len(output_grid))):
        for c in range(min(len(input_grid[0]), len(output_grid[0]))):
            if input_grid[r][c] != output_grid[r][c]:
                changes.append((input_grid[r][c], output_grid[r][c], (r, c)))
    return changes

